package org.canpshell.mobile;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.provider.DocumentsContract;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.util.*;

/** Only the dedicated exchange directory and the user's persisted SAF tree are exposed. */
final class AndroidManagedFiles implements AutoCloseable {
  private final Context context;private final File shared,staging;private final Map<String,Upload> uploads=new HashMap<>();
  private static final String APP="33a0cc50-958a-45cd-aa3b-171b476d04b7",DIR=DocumentsContract.Document.MIME_TYPE_DIR;
  private static final int CHUNK=65536;private static final long MAX_UPLOAD=512L*1024*1024;
  private static final class Upload {String owner,root,path,tree;File file;long size,offset,expires;}
  AndroidManagedFiles(Context c){context=c.getApplicationContext();shared=new File(context.getFilesDir(),"remote-shared");staging=new File(context.getCacheDir(),"remote-uploads");shared.mkdirs();staging.mkdirs();}
  private String safRoot()throws Exception{return UUID.nameUUIDFromBytes(tree(false).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
  private String path(String p)throws IOException {if(p.length()>4096||!p.startsWith("/")||p.indexOf('\\')>=0||p.indexOf('\0')>=0)throw new IOException("Invalid file path");if(p.equals("/"))return p;for(String n:p.substring(1).split("/",-1))if(n.isEmpty()||n.equals(".")||n.equals(".."))throw new IOException("Invalid file path");return p;}
  private File local(String p)throws IOException{File f=new File(shared,p.substring(1));String base=shared.getCanonicalPath(),actual=f.getCanonicalPath();if(!actual.equals(base)&&!actual.startsWith(base+File.separator))throw new SecurityException("File outside shared directory");return f;}
  private Uri tree(boolean write)throws Exception {String raw=context.getSharedPreferences("local-files",0).getString("tree","");if(raw.isEmpty())throw new IOException("请在手机文件页选择要共享的目录");Uri u=Uri.parse(raw);for(UriPermission p:context.getContentResolver().getPersistedUriPermissions())if(p.getUri().equals(u)&&p.isReadPermission()&&(!write||p.isWritePermission()))return u;throw new SecurityException("手机目录授权已撤销或为只读");}
  private Uri document(String p,boolean write)throws Exception{Uri t=tree(write),u=DocumentsContract.buildDocumentUriUsingTree(t,DocumentsContract.getTreeDocumentId(t));if(p.equals("/"))return u;for(String n:p.substring(1).split("/")){Uri found=null;try(Cursor c=context.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(t,DocumentsContract.getDocumentId(u)),new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("Cannot list directory");while(c.moveToNext())if(n.equals(c.getString(1))){if(found!=null)throw new IOException("Ambiguous file name");found=DocumentsContract.buildDocumentUriUsingTree(t,c.getString(0));}}if(found==null)throw new FileNotFoundException();u=found;}return u;}
  private JSONObject meta(Uri u,String p)throws Exception{try(Cursor c=context.getContentResolver().query(u,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},null,null,null)){if(c==null||!c.moveToFirst())throw new FileNotFoundException();return entry(c.getString(0),p,DIR.equals(c.getString(1)),c.isNull(2)?-1:c.getLong(2),c.isNull(3)?0:c.getLong(3));}}
  private JSONObject entry(String n,String p,boolean d,long size,long modified)throws Exception{return new JSONObject().put("name",n).put("path",p).put("directory",d).put("symlink",false).put("size",Math.max(0,size)).put("sizeKnown",size>=0).put("modified",modified);}
  private JSONObject stat(String r,String p)throws Exception{if(APP.equals(r)){File f=local(p);if(!f.exists())throw new FileNotFoundException();return entry(f.getName(),p,f.isDirectory(),f.length(),f.lastModified());}if(!APP.equals(r))return meta(document(p,false),p);throw new IOException("Unknown file root");}
  private InputStream input(String r,String p)throws Exception{return APP.equals(r)?new FileInputStream(local(p)):context.getContentResolver().openInputStream(document(p,false));}
  private boolean exists(String r,String p)throws Exception{try{stat(r,p);return true;}catch(FileNotFoundException e){return false;}}
  private String parent(String p)throws IOException{if(p.equals("/"))throw new IOException("Cannot modify root");int i=p.lastIndexOf('/');return i==0?"/":p.substring(0,i);}
  private String name(String p){return p.substring(p.lastIndexOf('/')+1);}
  private void expire(){long now=System.currentTimeMillis();Iterator<Upload> it=uploads.values().iterator();while(it.hasNext()){Upload u=it.next();if(u.expires<now){u.file.delete();it.remove();}}}
  synchronized Object call(String method,JSONObject p,String owner)throws Exception{
    expire();
    if(method.equals("files.roots")){JSONArray roots=new JSONArray().put(new JSONObject().put("root",APP).put("label","CAgent 共享文件"));try{tree(false);roots.put(new JSONObject().put("root",safRoot()).put("label","手机已授权目录"));}catch(Exception ignored){}return new JSONObject().put("roots",roots).put("chunkSize",CHUNK);}
    if(method.startsWith("files.upload")&&!method.equals("files.uploadStart"))return upload(method,p,owner);
    String r=p.getString("root"),f=path(p.getString("path"));if(!APP.equals(r)&&!safRoot().equals(r))throw new IOException("Unknown file root");
    if(method.equals("files.list")){JSONArray rows=new JSONArray();if(APP.equals(r)){File[] children=local(f).listFiles();if(children==null)throw new IOException("Not a directory");for(File c:children){String v=(f.equals("/")?"":f)+"/"+c.getName();try{local(v);rows.put(stat(r,v));}catch(SecurityException ignored){}if(rows.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>96000)throw new IOException("目录内容超过单次传输上限，请打开较小的子目录");}}else{Uri t=tree(false),u=document(f,false);try(Cursor c=context.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(t,DocumentsContract.getDocumentId(u)),new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("Cannot list directory");while(c.moveToNext()){String n=c.getString(1);if(n.indexOf('/')>=0||n.indexOf('\\')>=0)continue;rows.put(meta(DocumentsContract.buildDocumentUriUsingTree(t,c.getString(0)),(f.equals("/")?"":f)+"/"+n));if(rows.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>96000)throw new IOException("目录内容超过单次传输上限，请打开较小的子目录");}}}return new JSONObject().put("path",f).put("entries",rows);}
    if(method.equals("files.read")){JSONObject before=stat(r,f);if(before.getBoolean("directory")||!before.getBoolean("sizeKnown"))throw new IOException("File is not readable with a known size");long size=before.getLong("size"),offset=p.getLong("offset");String version=r+":"+f+":"+size+":"+before.getLong("modified");if(offset<0||offset>size||p.has("version")&&!version.equals(p.getString("version")))throw new IOException("File changed or invalid offset");byte[] bytes=new byte[(int)Math.min(CHUNK,size-offset)];try(InputStream in=input(r,f)){if(in==null)throw new IOException("Cannot read file");long left=offset;while(left>0){long n=in.skip(left);if(n==0){if(in.read()<0)throw new EOFException();n=1;}left-=n;}int done=0;while(done<bytes.length){int n=in.read(bytes,done,bytes.length-done);if(n<0)throw new EOFException();done+=n;}}JSONObject after=stat(r,f);if(after.getLong("size")!=size||after.getLong("modified")!=before.getLong("modified"))throw new IOException("File changed during download");return new JSONObject().put("data",Base64.encodeToString(bytes,Base64.NO_WRAP)).put("size",size).put("version",version).put("next",offset+bytes.length).put("done",offset+bytes.length==size);}
    if(method.equals("files.action")){String action=p.getString("action");parent(f);if(!APP.equals(r))tree(true);if(action.equals("mkdir")){if(exists(r,f))throw new IOException("Destination exists");if(APP.equals(r)){if(!local(f).mkdir())throw new IOException("Create directory failed");}else if(DocumentsContract.createDocument(context.getContentResolver(),document(parent(f),true),DIR,name(f))==null)throw new IOException("Create directory failed");}else if(action.equals("rename")){String to=path(p.getString("destination"));if(!parent(f).equals(parent(to)))throw new IOException("Rename must stay in its directory");if(exists(r,to))throw new IOException("Destination exists");if(APP.equals(r)){if(!local(f).renameTo(local(to)))throw new IOException("Rename failed");}else if(DocumentsContract.renameDocument(context.getContentResolver(),document(f,true),name(to))==null)throw new IOException("Rename failed");}else if(action.equals("delete")){if(APP.equals(r)){if(!local(f).delete())throw new IOException("Delete failed; directory must be empty");}else if(!DocumentsContract.deleteDocument(context.getContentResolver(),document(f,true)))throw new IOException("Delete failed");}else throw new IOException("Unknown file operation");return new JSONObject().put("ok",true);}
    if(method.equals("files.uploadStart")){long size=p.getLong("size");if(size<0||size>MAX_UPLOAD||uploads.size()>=4)throw new IOException("Upload exceeds limit");parent(f);if(exists(r,f))throw new IOException("Destination exists");if(!stat(r,parent(f)).getBoolean("directory"))throw new IOException("Not a directory");Upload u=new Upload();u.owner=owner;u.root=r;u.path=f;u.size=size;u.expires=System.currentTimeMillis()+1200000;u.tree=!APP.equals(r)?tree(true).toString():"";u.file=File.createTempFile("upload-",".part",staging);String id=UUID.randomUUID().toString();uploads.put(id,u);return new JSONObject().put("id",id).put("chunkSize",CHUNK);}
    throw new IOException("Unknown file operation");
  }
  JSONArray tools()throws Exception{
    JSONArray result=new JSONArray();
    for(String op:new String[]{"roots","list","read","action","uploadStart","uploadChunk","uploadFinish","uploadCancel"}){
      JSONObject props=new JSONObject();JSONArray required=new JSONArray();
      if(op.startsWith("upload")&&!op.equals("uploadStart")){props.put("id",new JSONObject().put("type","string").put("format","uuid"));required.put("id");}
      else if(!op.equals("roots")){for(String k:new String[]{"root","path"}){props.put(k,new JSONObject().put("type","string").put("maxLength",4096));required.put(k);}}
      if(op.equals("read")||op.equals("uploadChunk")){props.put("offset",new JSONObject().put("type","integer").put("minimum",0));required.put("offset");}
      if(op.equals("read"))props.put("version",new JSONObject().put("type","string"));
      if(op.equals("uploadStart")){props.put("size",new JSONObject().put("type","integer").put("minimum",0).put("maximum",MAX_UPLOAD));required.put("size");}
      if(op.equals("uploadChunk")){props.put("data",new JSONObject().put("type","string").put("maxLength",87384));required.put("data");}
      if(op.equals("action")){props.put("action",new JSONObject().put("type","string").put("enum",new JSONArray().put("mkdir").put("rename").put("delete")));props.put("destination",new JSONObject().put("type","string").put("maxLength",4096));required.put("action");}
      boolean write=!(op.equals("roots")||op.equals("list")||op.equals("read"));String id="android_files_"+op;
      result.put(new JSONObject().put("packageId","cagent.android").put("id",id).put("toolId",id).put("description","Android authorized shared-directory file operation: "+op+". Only CAgent exchange files and the phone-selected SAF tree are available; never arbitrary device files.").put("inputSchema",new JSONObject().put("type","object").put("properties",props).put("required",required).put("additionalProperties",false)).put("outputSchema",new JSONObject().put("type","object")).put("permissions",new JSONArray().put(write?"commands.execute":"files.read")).put("sideEffect",write));
    }return result;
  }
  private Object upload(String method,JSONObject p,String owner)throws Exception{String id=p.getString("id");Upload u=uploads.get(id);if(u==null||!u.owner.equals(owner))throw new IOException("Upload not found");if(method.equals("files.uploadCancel")){uploads.remove(id);u.file.delete();return new JSONObject().put("ok",true);}if(!APP.equals(u.root)&&!u.tree.equals(tree(true).toString()))throw new SecurityException("Shared directory changed");u.expires=System.currentTimeMillis()+1200000;
    if(method.equals("files.uploadChunk")){String raw=p.getString("data");if(raw.length()>87384)throw new IOException("Chunk too large");byte[] data=Base64.decode(raw,Base64.DEFAULT);if(data.length==0||data.length>CHUNK||!Base64.encodeToString(data,Base64.NO_WRAP).equals(raw)||p.getLong("offset")!=u.offset||u.offset+data.length>u.size)throw new IOException("Invalid upload chunk");try(FileOutputStream out=new FileOutputStream(u.file,true)){out.write(data);}u.offset+=data.length;return new JSONObject().put("next",u.offset);}
    if(!method.equals("files.uploadFinish")||u.offset!=u.size)throw new IOException("Upload incomplete");if(exists(u.root,u.path))throw new IOException("Destination exists");
    if(APP.equals(u.root)){File target=local(u.path);if(!target.createNewFile())throw new IOException("Destination exists");try{copy(u.file,new FileOutputStream(target));}catch(Exception e){target.delete();throw e;}}else{Uri target=DocumentsContract.createDocument(context.getContentResolver(),document(parent(u.path),true),"application/octet-stream",name(u.path));if(target==null)throw new IOException("Create file failed");try{if(!name(u.path).equals(meta(target,u.path).getString("name")))throw new IOException("Destination name changed");copy(u.file,context.getContentResolver().openOutputStream(target,"w"));}catch(Exception e){DocumentsContract.deleteDocument(context.getContentResolver(),target);throw e;}}
    uploads.remove(id);u.file.delete();return new JSONObject().put("ok",true);
  }
  private void copy(File from,OutputStream destination)throws Exception{if(destination==null)throw new IOException("Cannot write file");try(InputStream in=new FileInputStream(from);OutputStream out=destination){byte[] b=new byte[CHUNK];int n;while((n=in.read(b))>=0)out.write(b,0,n);}}
  public synchronized void close(){for(Upload u:uploads.values())u.file.delete();uploads.clear();}
}
